package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var DateRecVar DateRec

var dateFileScanner *bufio.Scanner
var dateFile *os.File

func formatNum(v int64, digits int) string {
	if digits <= 0 {
		return strconv.FormatInt(v, 10)
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// truncate high order digits: keep low-order
	v = v % mod
	if v < 0 {
		v += mod
	}
	s := strconv.FormatInt(v, 10)
	if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	} else if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func parseNum(s string, digits int) int64 {
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// keep only digits, but input should be digits
	// if contains spaces parse as 0? but spec says digits only
	n, err := strconv.ParseInt(strings.TrimSpace(s), 10, 64)
	if err != nil {
		// if non-numeric, treat as 0
		return 0
	}
	return n
}

func openFiles() {
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		// if file not exists, create empty scanner that is done
		dateFile = nil
		dateFileScanner = bufio.NewScanner(strings.NewReader(""))
		return
	}
	dateFileScanner = bufio.NewScanner(dateFile)
}

func READ_PARA() {
	if dateFileScanner.Scan() {
		line := dateFileScanner.Text()
		// LINE SEQUENTIAL: strip trailing \r if any (Scanner already)
		// pad with spaces on right to 12
		if len(line) < 12 {
			line = line + strings.Repeat(" ", 12-len(line))
		} else if len(line) > 12 {
			line = line[:12]
		}
		DateRecVar.DtId = line[0:4]
		DateRecVar.DtYyyy = parseNum(line[4:8], 4)
		DateRecVar.DtMm = parseNum(line[8:10], 2)
		DateRecVar.DtDd = parseNum(line[10:12], 2)
	} else {
		WsEofFlag = "Y"
	}
}

func LEAP_PARA() {
	WsQ = DateRecVar.DtYyyy / 4
	WsR4 = DateRecVar.DtYyyy % 4
	WsQ = DateRecVar.DtYyyy / 100
	WsR100 = DateRecVar.DtYyyy % 100
	WsQ = DateRecVar.DtYyyy / 400
	WsR400 = DateRecVar.DtYyyy % 400
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYS_PARA() {
	switch DateRecVar.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
}

func PROCESS_PARA() {
	LEAP_PARA()
	if DateRecVar.DtMm < 1 || DateRecVar.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		// DISPLAY DT-ID " BAD MONTH " DT-MM
		fmt.Println(DateRecVar.DtId + " BAD MONTH " + formatNum(DateRecVar.DtMm, 2))
	} else {
		DAYS_PARA()
		if DateRecVar.DtDd < 1 || DateRecVar.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			fmt.Println(DateRecVar.DtId + " BAD DAY " + formatNum(DateRecVar.DtDd, 2) + " MAX " + formatNum(WsMaxDay, 2))
		} else {
			WsValid = (WsValid + 1) % 100
			fmt.Println(DateRecVar.DtId + " VALID " + formatNum(DateRecVar.DtYyyy, 4) + "-" + formatNum(DateRecVar.DtMm, 2) + "-" + formatNum(DateRecVar.DtDd, 2))
		}
	}
	READ_PARA()
}

func main() {
	openFiles()
	if dateFile != nil {
		defer dateFile.Close()
	}
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	// CLOSE DATE-FILE already via defer
	fmt.Println("VALID: " + formatNum(WsValid, 2) + " BAD MONTH: " + formatNum(WsBadMonth, 2) + " BAD DAY: " + formatNum(WsBadDay, 2))
}
